python3 - << 'EOF'
import wave, numpy as np
for f in ['probe_a','probe_b','probe_c']:
    w = wave.open(f'/workspace/work/{f}.wav')
    print(f, w.getparams()[:4])
    raw = w.readframes(w.getnframes())
    if w.getsampwidth()==2:
        d = np.frombuffer(raw, dtype=np.int16).astype(float)
    elif w.getsampwidth()==4:
        d = np.frombuffer(raw, dtype=np.int32).astype(float)/65536
    else: d=np.zeros(1)
    print('  peak', np.abs(d).max())
EOF"}

